import {rescueTasks} from './learning.js';
export const districts=[['Hero Academy','Training begins here','★'],['Robot Rescue','A city full of new friends','⚙'],['Harbour Patrol','Set sail on a rescue','⚓'],['Skyway Station','Take your adventure higher','↗'],['Crystal Caves','Find the missing power crystals','◆'],['Gadget Quarter','Invent something incredible','✦'],['Wild Gardens','Help the city’s creatures','❋'],['Underground HQ','Uncover a secret message','⌁'],['Orbital Outpost','Reach for the stars','☾'],['Citywide Rescue','Bring your whole team together','⚑']];
export const rewards=['Academy badge','Signal gloves','Scout antenna','Rescue boots','Workshop lamp','Robot friend: Pip','Copper emblem','Headquarters plant','Signal cape','Robot friend: Dot','Comic wall','Academy champion badge'];
const build=(word)=>({type:'build',word,graphemes:[...word]});
const change=(from,word)=>({type:'change',from,word,graphemes:[...word]});
const story=(text,question,answers,correct)=>({type:'story',text,question,answers,correct});
const make=(id,title,subtitle,objective,scene,tasks)=>({id,title,subtitle,objective,scene,tasks,reward:rewards[id-1]});
const originalMissions=[
make(1,'Suit up!','Your first hero mission','Blend short a words','Our signal kit needs three words. An adult can say each word while you build it.',[build('sat'),build('pat'),build('tap')]),
make(2,'Send a signal','Connect the academy','Blend short i words','The signal tower is waking up. Build the words to connect its three power cells.',[build('sit'),build('pin'),build('tin')]),
make(3,'Find the lost kit','A little help for Pip','Change the first sound','Pip mixed up the workshop labels. Change one tile at a time to help put things right.',[change('sat','mat'),change('pin','tin'),change('tap','nap')]),
make(4,'Boots on the ground','Rescue team, ready','Blend short o words','A little robot is stuck on the training course. Let’s get the rescue equipment ready.',[build('dog'),build('pot'),build('top')]),
make(5,'Light the workshop','Bring back the power','Blend short e words','The workshop lights are out. Three word puzzles will get our repair station glowing.',[build('pet'),build('net'),build('pen')]),
make(6,'Meet your sidekick','A new friend joins you','Review short vowel words','You found Pip! Help finish the robot’s welcome kit. Asking for help is a hero skill.',[build('map'),build('sun'),build('dog')]),
make(7,'Fix the scanner','Small changes, big help','Change the last sound','The scanner has scrambled some words. Swap the last tile and fix the message.',[change('cat','cap'),change('pin','pit'),change('dog','dot')]),
make(8,'Grow your base','Make headquarters your own','Blend short u words','A plant delivery has arrived. Prepare its little corner of our headquarters.',[build('sun'),build('cup'),build('mud')]),
make(9,'Cape connection','Ready for the next rescue','Change the middle sound','Our new cape can catch signal waves. Change one vowel to tune it in.',[change('pan','pin'),change('pin','pen'),change('cap','cup')]),
make(10,'Robot roll call','Welcome another friend','Review and apply','Dot has joined the team! Show our new friend how the academy’s puzzles work.',[build('red'),change('mat','map'),build('bus')]),
make(11,'The missing map','Your first comic mission','Read and understand short text','Read with an adult if you like. We can explore the story together.',[story('Pip has a map. The map is in a bag.','Where is the map?',['In a bag','In a cup'],0),story('Dot has a red cap. Pip has a kit.','Who has a red cap?',['Pip','Dot'],1),story('The sun is hot. Pip sits on a mat.','What does Pip sit on?',['A mat','A bus'],0)]),
make(12,'Academy rescue','Your chapter finale','Combine familiar reading skills','Our friends need the final signal! Work together to restore the academy. There is no rush.',[build('map'),change('cap','cup'),story('Pip has a kit. Dot has a map. Pip and Dot get on a bus.','What do Pip and Dot get on?',['A bus','A bed'],0)])
];
const groups=['a','i','o','e','u','a','cvcc','ccvc','digraph','longer'];
export const levelDetails=[['cat','3'],['pin','3'],['dog','3'],['pen','3'],['sun','3'],['map','3'],['lamp','4'],['frog','4'],['ship','4'],['shell','5'],['map','Read'],['bus','★']];
export const missions=originalMissions.map((m,i)=>i<10?{...m,objective:'Listen, build and read: '+groups[i],tasks:rescueTasks(groups[i],Math.floor(i/3))}:m);
export const curriculum={status:'Demonstration content — educator review required',graphemes:['s','a','t','p','i','n','m','d','g','o','c','e','r','u','h','b','l','f','sh','ch','ck','ll'],introducedExceptionWords:['the','is','has','a','to','who','what','where','does'],note:'An adult introduces unfamiliar sounds and models blending. This prototype is not a validated intervention or a complete systematic phonics programme.'};
export function correctAnswer(task,answer){return ['story','listen','picture'].includes(task.type)?answer===task.correct:Array.isArray(answer)&&answer.join('')===task.word&&(!task.graphemes||(answer.length===task.graphemes.length&&answer.every((g,i)=>g===task.graphemes[i])));}
export function validateContent(){for(const m of missions){if(!m.tasks.length)throw Error('Empty mission');for(const t of m.tasks){if(t.type==='story'){if(!t.answers[t.correct])throw Error('Invalid story answer');}else if(['listen','picture'].includes(t.type)){if(t.options[t.correct]!==t.word||new Set(t.options).size!==t.options.length)throw Error('Invalid choice task');}else if(t.graphemes.join('')!==t.word)throw Error('Invalid segmentation');if(t.type==='change'&&([...t.from].filter((x,i)=>x!==t.graphemes[i]).length!==1||t.from.length!==t.graphemes.length))throw Error('Change must replace one tile');}}return true;}

